import { renderEquationSteps } from './equation-step-renderer.js';
import { PARTIAL_FRACTION_STRUCTURES, PARTIAL_FRACTION_EXAMPLES, LOG_LAWS } from './partial-fractions-data.js';
const slugs=['recognise-proper','improper-first','structure-builder','find-coefficients','integrate-terms','single-log'];
const IDS=new Set(slugs.map(s=>`activity:y13:integration:partial-fractions:understand:${s}`));
const el=(d,n,c='',t='')=>{const x=d.createElement(n);if(c)x.className=c;if(t)x.textContent=t;return x;};
const step=(id,label,expression,explanation)=>({id,kind:'working',label,expression,explanation});
export class PartialFractionsUnderstandExperience{
 constructor(host){if(!host)throw new Error('PartialFractionsUnderstandExperience requires a host.');this.host=host;this.document=host.ownerDocument||document;}
 supports(id){return IDS.has(id);} destroy(){this.host.replaceChildren();this.host.classList.remove('partial-fractions-understand');}
 render(id){if(!this.supports(id))return false;this.destroy();this.host.classList.add('partial-fractions-understand');this[`render_${id.split(':').at(-1).replaceAll('-','_')}`]();return true;}
 panel(title,eyebrow,lead){const p=el(this.document,'section','partial-fractions-understand__panel');const h=el(this.document,'div','partial-fractions-understand__header');h.append(el(this.document,'span','partial-fractions-understand__eyebrow',eyebrow),el(this.document,'h3','',title));const b=el(this.document,'div','partial-fractions-understand__body');if(lead)b.append(el(this.document,'p','partial-fractions-understand__lead',lead));p.append(h,b);this.host.append(p);return b;}
 render_recognise_proper(){const b=this.panel('Recognise the rational structure before doing calculus','32.1 · Recognise and check','Partial fractions is a method for rational functions. First compare polynomial degrees: decomposition starts only after the fraction is proper.');const grid=el(this.document,'div','partial-fractions-grid');for(const ex of PARTIAL_FRACTION_EXAMPLES.slice(0,3)){const c=el(this.document,'article','partial-fractions-card');c.append(el(this.document,'strong','',ex.expression),el(this.document,'span','partial-fractions-badge',ex.proper?'Proper: decompose':'Improper: divide first'),el(this.document,'p','',ex.proper?'The numerator degree is lower than the denominator degree.':'The degrees are equal, so polynomial division must happen first.'));grid.append(c);}b.append(grid);}
 render_improper_first(){const b=this.panel('Improper rational functions need division first','32.1 · Make proper','Do not force an improper fraction into a partial-fraction template. Divide, then decompose only the proper remainder.');const ex=PARTIAL_FRACTION_EXAMPLES.find(x=>x.id==='improper');const box=el(this.document,'div','partial-fractions-equations');b.append(box);renderEquationSteps(box,[step('i1','Original',ex.expression,'The numerator and denominator have the same degree.'),step('i2','Divide',ex.division,'Separate the polynomial quotient from the proper remainder.'),step('i3','Decompose remainder',ex.decomposition,'Now partial fractions is valid.'),step('i4','Integrate',ex.integrated,'Integrate the polynomial and simple fractions separately.')]);}
 render_structure_builder(){const b=this.panel('The denominator tells you the decomposition structure','32.1 · Structure first','Repeated factors are the main trap: every power up to the repeated power must appear.');const controls=el(this.document,'div','partial-fractions-controls');const out=el(this.document,'div','partial-fractions-structure-output');for(const s of PARTIAL_FRACTION_STRUCTURES){const btn=el(this.document,'button','partial-fractions-button',s.label);btn.type='button';btn.addEventListener('click',()=>{out.replaceChildren(el(this.document,'strong','',s.denominator),el(this.document,'span','partial-fractions-decomposition',s.decomposition),el(this.document,'p','',s.rule));});controls.append(btn);}b.append(controls,out);controls.firstElementChild?.click?.();}
 render_find_coefficients(){const b=this.panel('Choose a coefficient method that exposes information cleanly','32.1 · Find coefficients','Substitute convenient x-values when a factor can be zeroed. Compare coefficients when repeated structure or remaining unknowns make that clearer.');for(const ex of PARTIAL_FRACTION_EXAMPLES.filter(x=>x.id==='distinct'||x.id==='repeated')){const c=el(this.document,'article','partial-fractions-card');c.append(el(this.document,'strong','',ex.expression),el(this.document,'span','partial-fractions-badge',ex.coefficientMethod==='convenient-values'?'Convenient x-values':'Coefficient comparison'),el(this.document,'p','',`Verified decomposition: ${ex.decomposition}`));b.append(c);}}
 render_integrate_terms(){const b=this.panel('After decomposition, every term is a standard integral','32.2 · Algebra finished, calculus begins','A first-power linear denominator produces a logarithm. A repeated-factor term such as 1/(x−a)² is a power-rule integral, not another logarithm.');const repeated=PARTIAL_FRACTION_EXAMPLES.find(x=>x.id==='repeated');const distinct=PARTIAL_FRACTION_EXAMPLES.find(x=>x.id==='distinct');for(const ex of [distinct,repeated]){const c=el(this.document,'article','partial-fractions-card');c.append(el(this.document,'strong','',ex.decomposition),el(this.document,'p','partial-fractions-answer',`∫ = ${ex.integrated}`));b.append(c);}b.append(el(this.document,'div','partial-fractions-rule','Repeated-factor reminder: ∫(x−a)⁻² dx = −(x−a)⁻¹ + C.'))}
 render_single_log(){const b=this.panel('Combine logarithms only after the integration is correct','32.3 · Log laws stay visible','Use product, quotient and power laws explicitly. If a single logarithm including the arbitrary constant is required, write C=ln K with K>0.');const laws=el(this.document,'div','partial-fractions-log-laws');for(const law of LOG_LAWS){const row=el(this.document,'div','partial-fractions-log-law');row.append(el(this.document,'strong','',law.left),el(this.document,'span','',`= ${law.right}`));if(law.note)row.append(el(this.document,'p','',law.note));laws.append(row);}const ex=PARTIAL_FRACTION_EXAMPLES.find(x=>x.id==='distinct');b.append(laws,el(this.document,'div','partial-fractions-rule',`${ex.integrated} → ${ex.singleLog}`));}
}
export function createPartialFractionsUnderstandExperience(host){return new PartialFractionsUnderstandExperience(host);}
